package com.dy.artisan3d.ui.screen.main.aboutimport androidx.lifecycle.ViewModelimport androidx.lifecycle.viewModelScopeimport artisan3d.composeapp.generated.resources.Resimport artisan3d.composeapp.generated.resources.error_unknownimport com.dy.artisan3d.data.AppLanguageimport com.dy.artisan3d.domain.model.NetworkErrorimport com.dy.artisan3d.domain.repository.ArtisanAboutRepositoryimport com.dy.artisan3d.util.toErrorMessageimport kotlinx.coroutines.flow.MutableStateFlowimport kotlinx.coroutines.flow.asStateFlowimport kotlinx.coroutines.flow.updateimport kotlinx.coroutines.launchclass AboutViewModel(    private val aboutRepository: ArtisanAboutRepository,    private val appLanguage: AppLanguage) : ViewModel() {    private val _uiState = MutableStateFlow(AboutUiState())    val uiState = _uiState.asStateFlow()    init {        fetchAboutData()    }    fun fetchAboutData(){        viewModelScope.launch {            _uiState.update {                it.copy(                    isLoading = true                )            }            try {                val res = aboutRepository.getAboutData(lang = appLanguage.current)                _uiState.value = _uiState.value.copy(                    aboutData = res.getOrThrow(),                    isLoading = false,                    isError = false,                    error = null                )            }catch (e: Exception){                val errorMsg = if (e is NetworkError) {                    e.toErrorMessage()                } else {                    Res.string.error_unknown                }                _uiState.value = _uiState.value.copy(                    isLoading = false,                    isError = true,                    error = errorMsg                )            }        }    }}